import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State } from '@stencil/core';
import { handleAutofocus } from '../../utils/autofocus';
import { FocusHelper } from '../../utils/focus-helper';

/**
 * @nativeEvent click - dispatched when card was clicked
 *
 * @slot default - default slot for the content of the card
 */
@Component({
  tag: 'groupui-card',
  styleUrl: 'card.scss',
  shadow: true,
})
export class Card {
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly border: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly elevation;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly selected: boolean;

  /**
   * sets the background CSS-Property
   */
  @Prop({ reflect: true }) readonly background: string;

  /**
   * padding between card and content as css value (e.g.: 10px 20px 10px 20px)
   */
  @Prop({ reflect: true }) readonly padding: string;

  /**
   * sets the height CSS-Property
   */
  @Prop({ reflect: true }) readonly height: string;

  /**
   * enables the interactive mode
   */
  @Prop({ reflect: true }) readonly interactive: boolean = false;

  /**
   * enables highlight bar on left side using given color
   */
  @Prop({ reflect: true }) readonly highlightLeft: string;

  /**
   * enables highlight bar on right side using given color
   */
  @Prop({ reflect: true }) readonly highlightRight: string;

  @State() focusType: string = '';

  @Element() host: HTMLElement;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (this.interactive && event.code === 'Enter') {
      this.host.classList.add('active');
    }
  }

  @Listen('keyup')
  onKeyUp(event: KeyboardEvent) {
    if (this.interactive) {
      if (event.code === 'Enter') {
        this.host.dispatchEvent(new window.Event('click'));
        this.host.classList.remove('active');
      }

      this.focusType = FocusHelper.onKeyUp(this.focusType, event);
    }
  }

  @Listen('blur')
  onBlur() {
    this.focusType = FocusHelper.onBlur();
  }

  private readonly ACTIVE_TAB_INDEX = 0;

  componentWillLoad() {
    this.handleHostTabIndex();
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
    handleAutofocus(this.host);
  }

  private handleHostTabIndex = () => {
    if (this.interactive) {
      if (!this.host.getAttribute('tabIndex')) {
        this.host.setAttribute('tabIndex', `${this.ACTIVE_TAB_INDEX}`);
      }
    }
  };

  render() {
    return (
      <Host
        style={{ background: this.background, padding: this.padding && this.padding, height: this.height }}
        class={this.focusType}
        role="article"
      >
        {this.highlightLeft && <div class="highlight-left" style={{ backgroundColor: this.highlightLeft }}></div>}
        {this.highlightRight && <div class="highlight-right" style={{ backgroundColor: this.highlightRight }}></div>}
        <slot />
      </Host>
    );
  }
}
